            <?php if ($selectedRequest): ?>
                <section class="maintenance-admin-detail">
                    <div class="maintenance-admin-detail-head"><div><span class="dash-subtitle">REQUEST DETAILS</span><h2>Maintenance Request #<?php echo maintenanceRequestCode((int)$selectedRequest['id']); ?></h2></div><span class="maintenance-status-badge status-<?php echo htmlspecialchars($selectedRequest['status']); ?>"><?php echo htmlspecialchars(maintenanceStatusLabel($selectedRequest['status'])); ?></span></div>
                    <dl class="maintenance-admin-detail-grid"><div><dt>Resident</dt><dd><?php echo htmlspecialchars($selectedRequest['username']); ?> (<?php echo htmlspecialchars($selectedRequest['full_name']); ?>)</dd></div><div><dt>Unit</dt><dd><?php echo htmlspecialchars($selectedRequest['unit_number']); ?></dd></div><div><dt>Issue</dt><dd><?php echo htmlspecialchars($selectedRequest['issue_type']); ?></dd></div><div><dt>Location</dt><dd><?php echo htmlspecialchars($selectedRequest['location'] ?? 'Not specified'); ?></dd></div><div><dt>Date Submitted</dt><dd><?php echo htmlspecialchars(date('M j, Y', strtotime($selectedRequest['created_at']))); ?></dd></div><div><dt>Priority</dt><dd><?php echo htmlspecialchars(ucfirst($selectedRequest['urgency'] ?? 'normal')); ?></dd></div><div class="maintenance-admin-wide"><dt>Description</dt><dd><?php echo nl2br(htmlspecialchars($selectedRequest['description'])); ?></dd></div><?php if (!empty($selectedRequest['preferred_date'])): ?><div><dt>Preferred Schedule</dt><dd><?php echo htmlspecialchars(date('M j, Y', strtotime($selectedRequest['preferred_date']))); ?></dd></div><?php endif; ?><?php if (!empty($selectedRequest['completion_note'])): ?><div class="maintenance-admin-wide"><dt>Completion Notes</dt><dd><?php echo nl2br(htmlspecialchars($selectedRequest['completion_note'])); ?></dd></div><?php endif; ?></dl>
                    <div class="maintenance-admin-evidence"><?php foreach (['evidence_path' => 'Submitted Photo', 'before_photo_path' => 'Before Photo', 'after_photo_path' => 'After Photo'] as $field => $label): ?><?php if (!empty($selectedRequest[$field])): ?><a href="../maintenance_evidence.php?id=<?php echo (int)$selectedRequest['id']; ?>&amp;field=<?php echo rawurlencode($field); ?>" target="_blank" rel="noopener"><img src="../maintenance_evidence.php?id=<?php echo (int)$selectedRequest['id']; ?>&amp;field=<?php echo rawurlencode($field); ?>" alt="<?php echo htmlspecialchars($label); ?>"><span><?php echo htmlspecialchars($label); ?></span></a><?php endif; ?><?php endforeach; ?></div>
                    <div class="maintenance-admin-actions">
                        <a class="maintenance-back-button" href="maintenancerequests.php?tab=<?php echo $tabKey; ?>&amp;status=<?php echo rawurlencode($panelStatus); ?>&amp;search=<?php echo rawurlencode($search); ?>">Back to <?php echo $tabKey === 'history' ? 'history' : 'requests'; ?></a>
                        <?php if ($selectedRequest['status'] === 'pending' && canAccess('maintenance.review')): ?>
                            <form method="post" action="maintenancerequests.php?tab=<?php echo $tabKey; ?>&amp;status=<?php echo rawurlencode($panelStatus); ?>&amp;search=<?php echo rawurlencode($search); ?>&amp;view=<?php echo (int)$selectedRequest['id']; ?>" data-confirm="Approve maintenance request <?php echo htmlspecialchars(maintenanceRequestCode((int)$selectedRequest['id']), ENT_QUOTES, 'UTF-8'); ?>?" data-confirm-title="Approve maintenance request" data-confirm-action="Approve"><?php echo workflowCsrfField(); ?><input type="hidden" name="request_id" value="<?php echo (int)$selectedRequest['id']; ?>"><button class="maintenance-admin-button approve" name="action" value="approve">Approve</button></form>
                            <form method="post" action="maintenancerequests.php?tab=<?php echo $tabKey; ?>&amp;status=<?php echo rawurlencode($panelStatus); ?>&amp;search=<?php echo rawurlencode($search); ?>&amp;view=<?php echo (int)$selectedRequest['id']; ?>" data-confirm="Reject maintenance request <?php echo htmlspecialchars(maintenanceRequestCode((int)$selectedRequest['id']), ENT_QUOTES, 'UTF-8'); ?>? This cannot be undone." data-confirm-title="Reject maintenance request" data-confirm-action="Reject"><?php echo workflowCsrfField(); ?><input type="hidden" name="request_id" value="<?php echo (int)$selectedRequest['id']; ?>"><button class="maintenance-admin-button reject" name="action" value="reject">Reject</button></form>
                        <?php elseif ($selectedRequest['status'] === 'approved' || $selectedRequest['status'] === 'reopened'): ?>
                            <form method="post" action="maintenancerequests.php?tab=<?php echo $tabKey; ?>&amp;status=<?php echo rawurlencode($panelStatus); ?>&amp;search=<?php echo rawurlencode($search); ?>&amp;view=<?php echo (int)$selectedRequest['id']; ?>"><?php echo workflowCsrfField(); ?><input type="hidden" name="request_id" value="<?php echo (int)$selectedRequest['id']; ?>"><button class="maintenance-admin-button approve" name="action" value="<?php echo $selectedRequest['status'] === 'reopened' ? 'reopen_start' : 'start'; ?>">Start Work</button></form>
                        <?php endif; ?>
                    </div>
                    <?php if ($selectedRequest['status'] === 'in_progress'): ?>
                        <form method="post" action="maintenancerequests.php?tab=<?php echo $tabKey; ?>&amp;status=<?php echo rawurlencode($panelStatus); ?>&amp;search=<?php echo rawurlencode($search); ?>&amp;view=<?php echo (int)$selectedRequest['id']; ?>" enctype="multipart/form-data" class="maintenance-complete-form"><?php echo workflowCsrfField(); ?>
                            <input type="hidden" name="request_id" value="<?php echo (int)$selectedRequest['id']; ?>">
                            <input type="hidden" name="action" value="complete">
                            <label class="field-label">Completion Notes (optional)<textarea name="completion_note" rows="3" placeholder="Describe the work completed and verification..."></textarea></label>
                            <div class="maintenance-photo-fields"><label class="field-label">Before Photo (optional)<input type="file" name="before_photo" accept="image/jpeg,image/png,image/webp"></label><label class="field-label">After Photo (optional)<input type="file" name="after_photo" accept="image/jpeg,image/png,image/webp"></label></div>
                            <button class="maintenance-admin-button approve" type="submit">Mark Completed</button>
                        </form>
                    <?php endif; ?>
                </section>
            <?php endif; ?>

            <section class="maintenance-status-overview" aria-label="Request counts by status">
                <?php foreach ($panelStatuses as $status): ?><a href="maintenancerequests.php?tab=<?php echo $tabKey; ?>&amp;status=<?php echo rawurlencode($status); ?>" class="maintenance-status-summary"><span><?php echo htmlspecialchars(maintenanceStatusLabel($status)); ?></span><strong><?php echo $statusCounts[$status]; ?></strong></a><?php endforeach; ?>
            </section>

            <section class="unit-management-panel maintenance-admin-panel">
                <form class="unit-filters maintenance-admin-filters" method="get" action="maintenancerequests.php"><input type="hidden" name="tab" value="<?php echo $tabKey; ?>"><label for="requestStatus-<?php echo $tabKey; ?>">Status</label><select id="requestStatus-<?php echo $tabKey; ?>" name="status"><option value="all" <?php echo $panelStatus === 'all' ? 'selected' : ''; ?>>All statuses</option><?php foreach ($panelStatuses as $status): ?><option value="<?php echo htmlspecialchars($status); ?>" <?php echo $panelStatus === $status ? 'selected' : ''; ?>><?php echo htmlspecialchars(maintenanceStatusLabel($status)); ?></option><?php endforeach; ?></select><label class="maintenance-search-label" for="requestSearch-<?php echo $tabKey; ?>">Search</label><input type="search" id="requestSearch-<?php echo $tabKey; ?>" name="search" value="<?php echo htmlspecialchars($search); ?>" placeholder="Resident, unit, request ID, issue"><button type="submit">Filter</button></form>
                <div class="unit-table-wrap"><table class="unit-table maintenance-admin-table"><thead><tr><th>Request ID</th><th>Resident</th><th>Unit</th><th>Issue</th><th>Description</th><th>Date Submitted</th><th>Priority</th><th>Status</th><th>Action</th></tr></thead><tbody>
                    <?php if (!$requests): ?><tr><td colspan="9" class="unit-empty">No maintenance requests found.</td></tr><?php else: foreach ($requests as $request): ?><tr><td><strong><?php echo maintenanceRequestCode((int)$request['id']); ?></strong></td><td><strong><?php echo htmlspecialchars($request['username']); ?></strong><small><?php echo htmlspecialchars($request['full_name']); ?></small></td><td><?php echo htmlspecialchars($request['unit_number']); ?></td><td><?php echo htmlspecialchars($request['issue_type']); ?></td><td class="request-description"><?php echo htmlspecialchars($request['description']); ?></td><td><?php echo htmlspecialchars(date('M j, Y', strtotime($request['created_at']))); ?></td><td><span class="maintenance-urgency urgency-<?php echo htmlspecialchars($request['urgency'] ?? 'normal'); ?>"><?php echo htmlspecialchars(ucfirst($request['urgency'] ?? 'normal')); ?></span></td><td><span class="maintenance-status-badge status-<?php echo htmlspecialchars($request['status']); ?>"><?php echo htmlspecialchars(maintenanceStatusLabel($request['status'])); ?></span></td><td><a class="maintenance-view-link" href="maintenancerequests.php?tab=<?php echo $tabKey; ?>&amp;status=<?php echo rawurlencode($panelStatus); ?>&amp;search=<?php echo rawurlencode($search); ?>&amp;view=<?php echo (int)$request['id']; ?>">View</a></td></tr><?php endforeach; endif; ?>
                </tbody></table></div>
            </section>
